import { createServer } from 'node:http';



const SERVICE = 'billing';
const VERSION = '0.1.0';
const PORT = Number(process.env.PORT ?? 4001);
const BROKER_URL = process.env.BROKER_URL ?? 'localhost:9092';

const server = createServer((req, res) => {
  const url = (req.url ?? '/').split('?')[0];
  if (url === '/health' || url === '/ready') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok', service: SERVICE, version: VERSION }));
    return;
  }

  if (url === '/api/v1/billing' || url.startsWith('/api/v1/billing/')) {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(
      JSON.stringify({
        service: SERVICE,
        items: [],
        contract: 'contracts/openapi/billing.v1.yaml',
      })
    );
    return;
  }

  if (url === '/' || url === '/billing') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(
      JSON.stringify({
        service: SERVICE,
        version: VERSION,
        message: 'billing service is up',
      })
    );
    return;
  }

  res.writeHead(404, { 'content-type': 'application/json' });
  res.end(JSON.stringify({ error: 'not found' }));
});

server.listen(PORT, () => {
  console.log('[' + SERVICE + '] listening on http://localhost:' + PORT);
  console.log('[' + SERVICE + '] broker ' + BROKER_URL);
});

